import React, { useState, useRef, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import api from '../services/api';
import { useAuth } from '../context/AuthContext';
import ProfModal from './ProfModal';

/* ════════════════════════════════════════════════
   HELPERS
════════════════════════════════════════════════ */
function Stars({ n }) {
  const v = parseFloat(n) || 0;
  return (
    <span style={{ display: 'inline-flex', gap: 1 }}>
      {[1,2,3,4,5].map(i => (
        <span key={i} style={{ color: i <= Math.round(v) ? '#f59e0b' : '#d1d5db', fontSize: 12 }}>★</span>
      ))}
      <span style={{ fontSize: 11, color: '#6b7280', marginLeft: 3 }}>{v.toFixed(1)}</span>
    </span>
  );
}

function ScorePill({ score }) {
  const color = score >= 80 ? '#16a34a' : score >= 65 ? '#7c3aed' : score >= 50 ? '#d97706' : '#dc2626';
  const bg    = score >= 80 ? '#f0fdf4' : score >= 65 ? '#f5f3ff' : score >= 50 ? '#fffbeb' : '#fef2f2';
  const label = score >= 80 ? 'Excellent' : score >= 65 ? 'Très bon' : score >= 50 ? 'Bon' : 'Possible';
  return (
    <span style={{ display: 'inline-flex', alignItems: 'center', gap: 4, padding: '2px 8px', borderRadius: 20, background: bg, border: `1px solid ${color}30`, fontSize: 11, fontWeight: 700, color }}>
      <span style={{ width: 6, height: 6, borderRadius: '50%', background: color, display: 'inline-block' }} />
      {score}/100 · {label}
    </span>
  );
}

/* ════════════════════════════════════════════════
   CARTE PROF — DANS LA DISCUSSION
════════════════════════════════════════════════ */
function ProfCard({ prof, rank, onView }) {
  const [hov, setHov] = useState(false);
  const nom    = prof.nom || `${prof.user_prenom || ''} ${prof.user_nom || ''}`.trim();
  const score  = prof.score?.total || 0;
  const medals = ['🥇', '🥈', '🥉'];
  const tarifMin = Math.min(...[prof.tarif_en_ligne, prof.tarif_presentiel].filter(v => v && parseFloat(v) > 0).map(Number));
  const modeLabel = { en_ligne: '🌐 En ligne', presentiel: '🏫 Présentiel', les_deux: '🔀 Les deux' }[prof.mode_enseignement] || '🏫 Présentiel';
  const modeColor = { en_ligne: '#0ea5e9', presentiel: '#16a34a', les_deux: '#7c3aed' }[prof.mode_enseignement] || '#16a34a';

  return (
    <div
      onMouseEnter={() => setHov(true)}
      onMouseLeave={() => setHov(false)}
      style={{
        background: '#fff',
        border: hov ? '1.5px solid #6c63ff' : '1.5px solid #e5e7eb',
        borderRadius: 16,
        padding: '14px 16px',
        transition: 'all .2s',
        boxShadow: hov ? '0 8px 24px rgba(108,99,255,0.12)' : '0 1px 4px rgba(0,0,0,0.06)',
        cursor: 'default',
      }}
    >
      {/* Header */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 10 }}>
        <span style={{ fontSize: 18, flexShrink: 0 }}>{medals[rank - 1] || `#${rank}`}</span>
        <div style={{ width: 42, height: 42, borderRadius: '50%', background: 'linear-gradient(135deg,#6c63ff,#ff6584)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 16, overflow: 'hidden', flexShrink: 0 }}>
          {prof.photo_url
            ? <img src={`http://localhost:8001${prof.photo_url}`} alt="" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
            : '👨‍🏫'}
        </div>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontWeight: 700, fontSize: 14, color: '#111827', marginBottom: 2 }}>{nom}</div>
          <div style={{ display: 'flex', alignItems: 'center', gap: 6, flexWrap: 'wrap' }}>
            <Stars n={prof.note_moyenne} />
            {prof.ville && <span style={{ fontSize: 11, color: '#9ca3af' }}>📍 {prof.ville}</span>}
          </div>
        </div>
        <div style={{ flexShrink: 0, textAlign: 'right' }}>
          {isFinite(tarifMin) && (
            <div style={{ fontWeight: 800, fontSize: 14, color: '#16a34a' }}>{tarifMin} DT/h</div>
          )}
          <div style={{ fontSize: 11, color: modeColor, fontWeight: 600 }}>{modeLabel}</div>
        </div>
      </div>

      {/* Score matching */}
      <div style={{ marginBottom: 10 }}>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 4 }}>
          <span style={{ fontSize: 11, color: '#6b7280', fontWeight: 600 }}>Score de matching</span>
          <ScorePill score={score} />
        </div>
        <div style={{ height: 5, background: '#f3f4f6', borderRadius: 3, overflow: 'hidden' }}>
          <div style={{
            height: '100%', borderRadius: 3, transition: 'width .8s ease',
            width: `${score}%`,
            background: score >= 80 ? 'linear-gradient(90deg,#16a34a,#22c55e)'
                      : score >= 65 ? 'linear-gradient(90deg,#7c3aed,#8b5cf6)'
                      : score >= 50 ? 'linear-gradient(90deg,#d97706,#f59e0b)'
                      : 'linear-gradient(90deg,#dc2626,#ef4444)',
          }} />
        </div>
      </div>

      {/* Matières */}
      {prof.matieres && prof.matieres.length > 0 && (
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 4, marginBottom: 10 }}>
          {prof.matieres.slice(0, 4).map(m => (
            <span key={m} style={{ fontSize: 11, fontWeight: 600, padding: '2px 8px', borderRadius: 20, background: '#ede9fe', color: '#6c63ff', border: '1px solid #ddd6fe' }}>{m}</span>
          ))}
        </div>
      )}

      {/* Prochaine dispo */}
      {prof.disponibilites && prof.disponibilites.length > 0 && (
        <div style={{ fontSize: 11, color: '#374151', marginBottom: 10, padding: '5px 9px', background: '#f0fdf4', borderRadius: 8, border: '1px solid #bbf7d0' }}>
          📅 Prochain créneau : <strong>{prof.disponibilites[0].date}</strong> · {prof.disponibilites[0].heure_debut} – {prof.disponibilites[0].heure_fin}
        </div>
      )}

      {/* Bio */}
      {prof.bio && (
        <p style={{ fontSize: 12, color: '#6b7280', lineHeight: 1.5, margin: '0 0 10px', overflow: 'hidden', display: '-webkit-box', WebkitLineClamp: 2, WebkitBoxOrient: 'vertical' }}>
          {prof.bio}
        </p>
      )}

      {/* Actions */}
      <div style={{ display: 'flex', gap: 8 }}>
        <button
          onClick={() => onView(prof)}
          style={{ flex: 1, padding: '7px 0', background: '#f9fafb', border: '1.5px solid #e5e7eb', borderRadius: 9, fontSize: 12, fontWeight: 600, cursor: 'pointer', color: '#374151', transition: 'all .15s' }}
          onMouseEnter={e => { e.currentTarget.style.borderColor = '#6c63ff'; e.currentTarget.style.color = '#6c63ff'; e.currentTarget.style.background = '#f5f3ff'; }}
          onMouseLeave={e => { e.currentTarget.style.borderColor = '#e5e7eb'; e.currentTarget.style.color = '#374151'; e.currentTarget.style.background = '#f9fafb'; }}
        >
          👤 Voir profil complet
        </button>
        <button
          onClick={() => onView(prof)}
          style={{ flex: 2, padding: '7px 0', background: 'linear-gradient(135deg,#6c63ff,#8b5cf6)', border: 'none', borderRadius: 9, fontSize: 12, fontWeight: 700, cursor: 'pointer', color: '#fff', boxShadow: '0 2px 8px rgba(108,99,255,0.3)', transition: 'all .2s' }}
          onMouseEnter={e => e.currentTarget.style.transform = 'translateY(-1px)'}
          onMouseLeave={e => e.currentTarget.style.transform = 'none'}
        >
          📅 Réserver un cours
        </button>
      </div>
    </div>
  );
}

/* ════════════════════════════════════════════════
   MESSAGE — bulle de chat
════════════════════════════════════════════════ */
function Message({ msg, onViewProf }) {
  const isUser = msg.role === 'user';

  return (
    <div style={{ display: 'flex', flexDirection: 'column', alignItems: isUser ? 'flex-end' : 'flex-start', marginBottom: 20, gap: 6 }}>
      {/* Bulle texte */}
      {msg.content && (
        <div style={{ display: 'flex', alignItems: 'flex-end', gap: 8, maxWidth: '82%', flexDirection: isUser ? 'row-reverse' : 'row' }}>
          {/* Avatar */}
          <div style={{ width: 32, height: 32, borderRadius: '50%', flexShrink: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 14, background: isUser ? 'linear-gradient(135deg,#6c63ff,#8b5cf6)' : 'linear-gradient(135deg,#f59e0b,#ef4444)' }}>
            {isUser ? '👤' : '🤖'}
          </div>
          <div>
            <div style={{
              padding: '11px 15px',
              borderRadius: isUser ? '18px 18px 4px 18px' : '18px 18px 18px 4px',
              background: isUser ? 'linear-gradient(135deg,#6c63ff,#8b5cf6)' : '#fff',
              color: isUser ? '#fff' : '#111827',
              fontSize: 14,
              lineHeight: 1.65,
              border: isUser ? 'none' : '1px solid #e5e7eb',
              boxShadow: isUser ? '0 2px 8px rgba(108,99,255,0.25)' : '0 1px 4px rgba(0,0,0,0.05)',
              whiteSpace: 'pre-wrap',
              wordBreak: 'break-word',
            }}>
              {msg.content}
            </div>
            <div style={{ fontSize: 11, color: '#9ca3af', marginTop: 3, textAlign: isUser ? 'right' : 'left' }}>
              {msg.time}
            </div>
          </div>
        </div>
      )}

      {/* Cartes profs sous le message bot */}
      {!isUser && msg.profs && msg.profs.length > 0 && (
        <div style={{ width: '100%', maxWidth: 520, display: 'flex', flexDirection: 'column', gap: 10, marginTop: 4, paddingLeft: 40 }}>
          {msg.profs.map((prof, i) => (
            <ProfCard key={prof.id} prof={prof} rank={i + 1} onView={onViewProf} />
          ))}
        </div>
      )}
    </div>
  );
}

/* ════════════════════════════════════════════════
   TYPING INDICATOR
════════════════════════════════════════════════ */
function Typing() {
  return (
    <div style={{ display: 'flex', alignItems: 'flex-end', gap: 8, marginBottom: 16 }}>
      <div style={{ width: 32, height: 32, borderRadius: '50%', background: 'linear-gradient(135deg,#f59e0b,#ef4444)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 14, flexShrink: 0 }}>🤖</div>
      <div style={{ padding: '11px 16px', background: '#fff', border: '1px solid #e5e7eb', borderRadius: '18px 18px 18px 4px', display: 'flex', gap: 5, alignItems: 'center', boxShadow: '0 1px 4px rgba(0,0,0,0.05)' }}>
        <style>{`
          @keyframes dotBounce { 0%,60%,100%{transform:translateY(0)} 30%{transform:translateY(-6px)} }
          .dot { width:7px;height:7px;border-radius:50%;background:#6c63ff;animation:dotBounce 1.2s infinite; }
        `}</style>
        <div className="dot" style={{ animationDelay: '0s' }} />
        <div className="dot" style={{ animationDelay: '.15s' }} />
        <div className="dot" style={{ animationDelay: '.3s' }} />
      </div>
    </div>
  );
}

/* ════════════════════════════════════════════════
   SUGGESTIONS RAPIDES
════════════════════════════════════════════════ */
const QUICK = [
  "Je cherche un prof de maths pour préparer le bac",
  "Cours de physique en ligne, budget 40 DT/h",
  "Professeur d'anglais pour mon enfant au collège",
  "Cours de programmation Python pour débutant",
  "Prof de français présentiel à Tunis",
];

/* ════════════════════════════════════════════════
   PAGE PRINCIPALE
════════════════════════════════════════════════ */
export default function Chatbot() {
  const { user }     = useAuth();
  const navigate     = useNavigate();
  const [msgs, setMsgs]           = useState([]);
  const [input, setInput]         = useState('');
  const [loading, setLoading]     = useState(false);
  const [selectedProf, setSelectedProf] = useState(null);
  const [showWelcome, setShowWelcome]   = useState(true);
  const bottomRef = useRef(null);
  const inputRef  = useRef(null);
  const textareaRef = useRef(null);

  useEffect(() => { bottomRef.current?.scrollIntoView({ behavior: 'smooth' }); }, [msgs, loading]);
  useEffect(() => { inputRef.current?.focus(); }, []);

  const now = () => new Date().toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' });

  const handleViewProf = async (prof) => {
    try {
      const res = await api.get(`/api/chatbot/prof-detail/${prof.id}`);
      setSelectedProf(res.data);
    } catch {
      setSelectedProf(prof);
    }
  };

  const send = useCallback(async (text) => {
    const txt = (text || input).trim();
    if (!txt || loading) return;

    setInput('');
    setShowWelcome(false);
    if (textareaRef.current) { textareaRef.current.style.height = 'auto'; }

    const userMsg = { role: 'user', content: txt, time: now() };
    setMsgs(prev => [...prev, userMsg]);
    setLoading(true);

    // Historique pour l'API (sans les champs UI)
    const history = [...msgs, userMsg].map(m => ({ role: m.role, content: m.content }));

    try {
      const res = await api.post('/api/chatbot/chat', { messages: history });
      const { reply, top3_profs } = res.data;

      setMsgs(prev => [...prev, {
        role:    'assistant',
        content: reply,
        time:    now(),
        profs:   top3_profs && top3_profs.length > 0 ? top3_profs : [],
      }]);
    } catch (e) {
      const status = e?.response?.status;
      const detail = e?.response?.data?.detail;
      let errMsg = '❌ Une erreur est survenue. Réessayez.';
      if (status === 503) errMsg = '⏳ Le modèle IA démarre (30s). Réessayez dans quelques secondes.';
      else if (status === 429) errMsg = '⚠️ Trop de requêtes. Attendez quelques secondes.';
      else if (status === 504) errMsg = '⏱️ Le modèle a pris trop de temps. Réessayez.';
      else if (detail) errMsg = `❌ ${detail}`;

      setMsgs(prev => [...prev, { role: 'assistant', content: errMsg, time: now(), profs: [] }]);
    } finally {
      setLoading(false);
      setTimeout(() => inputRef.current?.focus(), 100);
    }
  }, [input, msgs, loading]);

  const onKey = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); send(); }
  };

  const reset = () => { setMsgs([]); setShowWelcome(true); setInput(''); };

  return (
    <div style={{ display: 'flex', height: 'calc(100vh - 64px)', background: '#f9fafb', fontFamily: 'inherit' }}>
      <style>{`
        .chat-scroll::-webkit-scrollbar{width:4px}
        .chat-scroll::-webkit-scrollbar-track{background:transparent}
        .chat-scroll::-webkit-scrollbar-thumb{background:#d1d5db;border-radius:2px}
      `}</style>

      {/* ════ ZONE CHAT ════ */}
      <div style={{ flex: 1, display: 'flex', flexDirection: 'column', minWidth: 0 }}>

        {/* Header */}
        <div style={{ padding: '14px 24px', background: '#fff', borderBottom: '1px solid #e5e7eb', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
            <div style={{ width: 42, height: 42, borderRadius: 12, background: 'linear-gradient(135deg,#6c63ff,#8b5cf6)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 18, boxShadow: '0 3px 10px rgba(108,99,255,0.3)' }}>🤖</div>
            <div>
              <div style={{ fontWeight: 700, fontSize: 15, color: '#111827' }}>EduBot — Assistant de matching</div>
              <div style={{ fontSize: 12, color: '#6b7280', display: 'flex', alignItems: 'center', gap: 5 }}>
                <span style={{ width: 6, height: 6, borderRadius: '50%', background: '#22c55e', display: 'inline-block' }} />
                Propulsé par IA · Trouve ton prof idéal
              </div>
            </div>
          </div>
          <button onClick={reset} style={{ padding: '7px 14px', background: '#f3f4f6', border: '1px solid #e5e7eb', borderRadius: 9, cursor: 'pointer', fontSize: 12, color: '#6b7280', fontWeight: 600, display: 'flex', alignItems: 'center', gap: 5 }}>
            🔄 Nouvelle conversation
          </button>
        </div>

        {/* Messages */}
        <div className="chat-scroll" style={{ flex: 1, overflowY: 'auto', padding: '24px 24px 16px' }}>

          {/* Écran de bienvenue */}
          {showWelcome && (
            <div style={{ textAlign: 'center', padding: '32px 20px 24px' }}>
              <div style={{ fontSize: 48, marginBottom: 16 }}>🎓</div>
              <h2 style={{ fontFamily: 'Syne,sans-serif', fontSize: '1.35rem', fontWeight: 800, margin: '0 0 8px', color: '#111827' }}>
                Bonjour {user?.prenom} !
              </h2>
              <p style={{ color: '#6b7280', fontSize: 14, lineHeight: 1.7, maxWidth: 440, margin: '0 auto 28px' }}>
                Je suis EduBot. Décris-moi ton besoin en langage naturel et je te trouve les 3 professeurs les plus adaptés avec un score de matching personnalisé.
              </p>

              {/* Quick replies */}
              <div style={{ marginBottom: 28 }}>
                <div style={{ fontSize: 11, fontWeight: 700, color: '#9ca3af', textTransform: 'uppercase', letterSpacing: '.06em', marginBottom: 10 }}>
                  💡 Exemples de recherche
                </div>
                <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8, justifyContent: 'center' }}>
                  {QUICK.map(q => (
                    <button key={q} onClick={() => send(q)}
                      style={{ padding: '8px 14px', background: '#fff', border: '1.5px solid #e5e7eb', borderRadius: 20, cursor: 'pointer', fontSize: 12.5, color: '#374151', fontWeight: 500, transition: 'all .15s', textAlign: 'left' }}
                      onMouseEnter={e => { e.currentTarget.style.borderColor='#6c63ff'; e.currentTarget.style.color='#6c63ff'; e.currentTarget.style.background='#f5f3ff'; }}
                      onMouseLeave={e => { e.currentTarget.style.borderColor='#e5e7eb'; e.currentTarget.style.color='#374151'; e.currentTarget.style.background='#fff'; }}
                    >
                      {q}
                    </button>
                  ))}
                </div>
              </div>

              {/* Features */}
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3,1fr)', gap: 10, maxWidth: 520, margin: '0 auto' }}>
                {[
                  { icon: '🧠', title: 'IA intelligente', desc: 'Comprend le langage naturel' },
                  { icon: '🎯', title: 'Matching précis', desc: 'Score sur 6 critères' },
                  { icon: '📅', title: 'Réservation directe', desc: 'En un clic depuis le chat' },
                ].map(f => (
                  <div key={f.title} style={{ padding: 14, background: '#fff', border: '1px solid #e5e7eb', borderRadius: 12 }}>
                    <div style={{ fontSize: 20, marginBottom: 6 }}>{f.icon}</div>
                    <div style={{ fontWeight: 700, fontSize: 12, marginBottom: 3, color: '#111827' }}>{f.title}</div>
                    <div style={{ fontSize: 11, color: '#9ca3af' }}>{f.desc}</div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Messages */}
          {msgs.map((msg, i) => <Message key={i} msg={msg} onViewProf={handleViewProf} />)}

          {/* Typing */}
          {loading && <Typing />}

          <div ref={bottomRef} />
        </div>

        {/* Input */}
        <div style={{ padding: '12px 24px 16px', background: '#fff', borderTop: '1px solid #e5e7eb' }}>
          <div style={{ display: 'flex', gap: 10, alignItems: 'flex-end', background: '#f9fafb', border: '1.5px solid #e5e7eb', borderRadius: 16, padding: '8px 10px 8px 16px', transition: 'border-color .2s' }}
            onFocusCapture={e => e.currentTarget.style.borderColor = '#6c63ff'}
            onBlurCapture={e => e.currentTarget.style.borderColor = '#e5e7eb'}
          >
            <textarea
              ref={el => { inputRef.current = el; textareaRef.current = el; }}
              value={input}
              onChange={e => setInput(e.target.value)}
              onKeyDown={onKey}
              placeholder="Ex: Je cherche un prof de maths pour mon fils en terminale, en ligne si possible..."
              rows={1}
              style={{ flex: 1, background: 'none', border: 'none', outline: 'none', color: '#111827', fontSize: 14, lineHeight: 1.55, resize: 'none', maxHeight: 120, fontFamily: 'inherit', paddingTop: 4, paddingBottom: 4, overflowY: 'auto' }}
              onInput={e => { e.target.style.height = 'auto'; e.target.style.height = Math.min(e.target.scrollHeight, 120) + 'px'; }}
            />
            <button
              onClick={() => send()}
              disabled={!input.trim() || loading}
              style={{
                width: 40, height: 40, borderRadius: 11, border: 'none', cursor: !input.trim() || loading ? 'not-allowed' : 'pointer',
                background: !input.trim() || loading ? '#e5e7eb' : 'linear-gradient(135deg,#6c63ff,#8b5cf6)',
                color: '#fff', fontSize: 16, display: 'flex', alignItems: 'center', justifyContent: 'center',
                transition: 'all .2s', flexShrink: 0,
                boxShadow: input.trim() && !loading ? '0 3px 10px rgba(108,99,255,0.3)' : 'none',
              }}
            >
              {loading ? '⏳' : '➤'}
            </button>
          </div>
          <div style={{ fontSize: 11, color: '#9ca3af', marginTop: 5, textAlign: 'center' }}>
            Entrée pour envoyer · Shift+Entrée pour nouvelle ligne
          </div>
        </div>
      </div>

      {/* ════ PANNEAU LATÉRAL ════ */}
      <div style={{ width: 300, background: '#fff', borderLeft: '1px solid #e5e7eb', display: 'flex', flexDirection: 'column', flexShrink: 0 }}>
        <div style={{ padding: '18px 18px 12px', borderBottom: '1px solid #f3f4f6' }}>
          <div style={{ fontWeight: 700, fontSize: 14, color: '#111827', marginBottom: 2 }}>💡 Comment bien chercher</div>
          <div style={{ fontSize: 12, color: '#6b7280' }}>L'IA comprend le langage naturel</div>
        </div>
        <div style={{ padding: '14px 18px', flex: 1, overflowY: 'auto' }}>
          {[
            { icon: '📚', tip: 'Mentionnez la matière', ex: '"prof de maths"' },
            { icon: '🎓', tip: 'Précisez le niveau', ex: '"pour le bac", "collège"' },
            { icon: '📡', tip: 'Indiquez le mode', ex: '"en ligne", "à domicile"' },
            { icon: '💰', tip: 'Donnez votre budget', ex: '"max 40 DT/h"' },
            { icon: '📍', tip: 'Mentionnez votre ville', ex: '"à Tunis", "Sfax"' },
          ].map(t => (
            <div key={t.tip} style={{ marginBottom: 12, padding: '10px 12px', background: '#f9fafb', borderRadius: 10, border: '1px solid #f3f4f6' }}>
              <div style={{ display: 'flex', gap: 8, alignItems: 'flex-start' }}>
                <span style={{ fontSize: 14, flexShrink: 0 }}>{t.icon}</span>
                <div>
                  <div style={{ fontWeight: 600, fontSize: 12, color: '#374151', marginBottom: 2 }}>{t.tip}</div>
                  <div style={{ fontSize: 11, color: '#9ca3af', fontStyle: 'italic' }}>{t.ex}</div>
                </div>
              </div>
            </div>
          ))}

          <div style={{ marginTop: 8, padding: '12px', background: '#f5f3ff', borderRadius: 10, border: '1px solid #ede9fe' }}>
            <div style={{ fontSize: 12, fontWeight: 700, color: '#6c63ff', marginBottom: 6 }}>📊 Barème de matching</div>
            {[
              ['🟢', '80-100', 'Excellent'],
              ['🔵', '65-79',  'Très bon'],
              ['🟡', '50-64',  'Bon'],
              ['🔴', '< 50',   'Possible'],
            ].map(([dot, range, label]) => (
              <div key={range} style={{ display: 'flex', gap: 6, alignItems: 'center', marginBottom: 4, fontSize: 11, color: '#6b7280' }}>
                <span style={{ fontSize: 10 }}>{dot}</span>
                <span style={{ fontWeight: 600, minWidth: 40 }}>{range}</span>
                <span>{label}</span>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Modal profil */}
      {selectedProf && <ProfModal prof={selectedProf} onClose={() => setSelectedProf(null)} />}
    </div>
  );
}
